import "date"
// Whole windows only: the range starts on a quarter hour and the partial last window is dropped, so neither edge reads as a dip.
from(bucket:"smokeping") |> range(start: date.truncate(t: v.timeRangeStart, unit: 15m), stop: v.timeRangeStop) |> filter(fn:(r) => r._measurement == "latency" and r._field == "loss") |> set(key:"_field", value:"ICMP") |> group(columns:["_field"]) |> aggregateWindow(every: 15m, fn: count, createEmpty: true) |> filter(fn:(r) => r._time < v.timeRangeStop)

